def maxSubarraySum(a):

    maxSum = currentSum = 0

    for number in a:

        currentSum += number

        if currentSum < 0:

            currentSum = 0

        maxSum = max(currentSum, maxSum)

    if maxSum < 0:

        maxSum = 0

    return maxSum

